import{_ as s,o as t,c as a,a2 as n}from"./chunks/framework.Mk3aTUWd.js";const u=JSON.parse('{"title":"Project structure","description":"","frontmatter":{},"headers":[],"relativePath":"guide/project-structure.md","filePath":"guide/project-structure.md","lastUpdated":1794401238000}'),o={name:"guide/project-structure.md"};function i(r,e,p,d,l,c){return t(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="project-structure" tabindex="-1">Project structure <a class="header-anchor" href="#project-structure" aria-label="Permalink to &quot;Project structure&quot;">​</a></h1><p>A project created by the setup script looks like this. Projects that add ktor-svelte to an existing app have the same core: a Gradle build with the plugin, a Ktor app with <code>install(Svelte)</code>, and a SvelteKit app in <code>frontend/</code>.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-app/</span></span>
<span class="line"><span>  build.gradle.kts            plugins, svelte { } settings, dependencies</span></span>
<span class="line"><span>  settings.gradle.kts</span></span>
<span class="line"><span>  gradle/libs.versions.toml   version catalog</span></span>
<span class="line"><span>  src/main/kotlin/</span></span>
<span class="line"><span>    Application.kt            embeddedServer, install(Svelte), routes</span></span>
<span class="line"><span>    Env.kt                    typed access to environment variables</span></span>
<span class="line"><span>    Errors.kt                 typed error responses</span></span>
<span class="line"><span>  src/main/resources/</span></span>
<span class="line"><span>    logback.xml</span></span>
<span class="line"><span>  frontend/</span></span>
<span class="line"><span>    package.json</span></span>
<span class="line"><span>    vite.config.ts            generated by ktor-svelte</span></span>
<span class="line"><span>    vite.user.ts              your own Vite settings</span></span>
<span class="line"><span>    src/</span></span>
<span class="line"><span>      app.html</span></span>
<span class="line"><span>      routes/                 your pages</span></span>
<span class="line"><span>      lib/api/                generated TypeScript client</span></span>
<span class="line"><span>      lib/ktor-svelte/        generated helpers for themes, icons and i18n</span></span>
<span class="line"><span>    messages/                 i18n message files, if i18n is on</span></span>
<span class="line"><span>  .run/                       IntelliJ run configurations</span></span>
<span class="line"><span>  .env.example                every variable the app reads</span></span>
<span class="line"><span>  Dockerfile                  if you chose Docker</span></span></code></pre></div><h2 id="files-you-own-and-files-ktor-svelte-owns" tabindex="-1">Files you own and files ktor-svelte owns <a class="header-anchor" href="#files-you-own-and-files-ktor-svelte-owns" aria-label="Permalink to &quot;Files you own and files ktor-svelte owns&quot;">​</a></h2><p>ktor-svelte writes some files for you and keeps them up to date. Each of them starts with a &quot;Generated by ktor-svelte&quot; header. Do not edit them, because the next sync or start overwrites your changes.</p><table tabindex="0"><thead><tr><th>File</th><th>Written by</th><th>Changes when</th></tr></thead><tbody><tr><td><code>frontend/src/lib/api/*</code></td><td>the app in development, or <code>svelteGenerateTs</code></td><td>a route or DTO changes</td></tr><tr><td><code>frontend/vite.config.ts</code></td><td><code>svelteSync</code></td><td>library settings change</td></tr><tr><td><code>frontend/src/lib/ktor-svelte/*</code></td><td><code>svelteSync</code></td><td>themes, icons or locales change</td></tr><tr><td><code>frontend/src/hooks*.ts</code></td><td><code>svelteSync</code></td><td>i18n or theme settings change</td></tr><tr><td>Kotlin <code>AppTheme</code> and <code>Messages</code> classes</td><td>the Gradle build, in <code>build/generated</code>, never committed</td><td>themes or messages change</td></tr></tbody></table><p>Everything else is yours. ktor-svelte never overwrites a file without the header. If it needs to own a file you already have, such as your own <code>vite.config.ts</code>, the build stops and tells you what to move. Put custom Vite settings in <code>vite.user.ts</code>.</p><p>Commit the generated frontend files. A frontend build never needs the JVM app to run first, and <code>svelteVerifyTs</code> and <code>svelteVerifySync</code> in <code>check</code> fail when they are out of date, so a changed DTO cannot drift away from the frontend unnoticed.</p><h2 id="the-api-import" tabindex="-1">The <code>#api</code> import <a class="header-anchor" href="#the-api-import" aria-label="Permalink to &quot;The \`#api\` import&quot;">​</a></h2><p><code>svelteInit</code> and <code>svelteSync</code> add an import alias to <code>frontend/package.json</code>, so pages import the generated client the same way wherever they are:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { api, isApiError, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Note } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;#api&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><h2 id="what-ends-up-in-the-jar" tabindex="-1">What ends up in the JAR <a class="header-anchor" href="#what-ends-up-in-the-jar" aria-label="Permalink to &quot;What ends up in the JAR&quot;">​</a></h2><p><code>svelteBundle</code> copies the static build into <code>ktor-svelte/public/</code> in your resources and writes <code>ktor-svelte/manifest.json</code>. Hidden files such as <code>.env</code> and source maps are left out. The <a href="./../reference/how-it-works">How it works</a> page explains how requests are answered from the manifest.</p>`,13)])])}const g=s(o,[["render",i]]);export{u as __pageData,g as default};
